package com.example.taskmanager.controller;
import com.example.taskmanager.dto.TaskRequest; import com.example.taskmanager.model.Task; import com.example.taskmanager.service.TaskService; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/tasks") @CrossOrigin(origins="http://localhost:5173") public class TaskController { final TaskService s; public TaskController(TaskService s){this.s=s;} String email(@RequestHeader("X-User-Email") String e){return e;} @GetMapping public List<Task> all(@RequestHeader("X-User-Email") String e){return s.all(e);} @PostMapping public Task create(@RequestHeader("X-User-Email") String e,@RequestBody TaskRequest x){return s.save(e,x);} @PutMapping("/{id}") public Task update(@RequestHeader("X-User-Email") String e,@PathVariable Long id,@RequestBody TaskRequest x){return s.update(e,id,x);} @DeleteMapping("/{id}") public void delete(@RequestHeader("X-User-Email") String e,@PathVariable Long id){s.delete(e,id);} @GetMapping("/stats") public Map<String,Object> stats(@RequestHeader("X-User-Email") String e){return s.stats(e);} }
